// Deploy independently: this scheduler uses no AI and keeps the Mac asleep.
export interface Env {SITE_URL:string;SERVICE_SECRET:string;SITE_ACCESS_TOKEN:string;}
export default {async scheduled(_controller:ScheduledController,env:Env,ctx:ExecutionContext){ctx.waitUntil((async()=>{const response=await fetch(new URL('/api/service/run',env.SITE_URL),{method:'POST',headers:{Authorization:`Bearer ${env.SERVICE_SECRET}`,'OAI-Sites-Authorization':`Bearer ${env.SITE_ACCESS_TOKEN}`}});if(!response.ok)throw new Error(`Quest Island scheduled check failed: ${response.status}`);const result=await response.json() as {results:{error?:boolean}[]};if(result.results.some(r=>r.error))throw new Error('Quest Island background check reported a failure. Check the site connection health.');})());}};
